        (!isfinite(process_noise_rad2_s)) || (dt_s < 0.0) || (process_noise_rad2_s < 0.0)) {
        return ADCS_E_RANGE;
    }

    adcs_mat3_t F, Ft_matrix, T1, M;
    size_t i, j;

    // Construct the right-handed skew matrix [omega]x based on the normative map
    double w_x = body_rate_rad_s->x;
    double w_y = body_rate_rad_s->y;
    double w_z = body_rate_rad_s->z;

    adcs_mat3_t skew;
    skew.m[0][0] = 0.0;
    skew.m[0][1] = -w_z;
    skew.m[0][2] = w_y;
    skew.m[1][0] = w_z;
    skew.m[1][1] = 0.0;
    skew.m[1][2] = -w_x;
    skew.m[2][0] = -w_y;
    skew.m[2][1] = w_x;
    skew.m[2][2] = 0.0;

    // Calculate F = I - dt * [omega]x
    adcs_mat3_t I = adcs_mat3_identity();
    adcs_mat3_t neg_dt_skew = adcs_mat3_scale(&skew, -dt_s);
    F = adcs_mat3_add(&I, &neg_dt_skew);

    // Calculate M = F * P * F^T
    // First product: T1 = F * P
    T1 = adcs_mat3_mul(&F, covariance);

    // Transpose of F
    Ft_matrix = adcs_mat3_transpose(&F);

    // Second product: M = T1 * F^T
    M = adcs_mat3_mul(&T1, &Ft_matrix);

    // Add process noise to the diagonal: P_next = M + process_noise * dt * I
    double noise_val = process_noise_rad2_s * dt_s;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (i == j) {
                propagated->m[i][j] = M.m[i][j] + noise_val;
            } else {
                propagated->m[i][j] = M.m[i][j];
            }
        }
    }

    return ADCS_OK;
}

